 static int checks;static void Check(bool ok,string text){if(!ok)throw new Exception("N FAIL: "+text);checks++;Console.WriteLine("N PASS: "+text);}
 static DemoWorld World(){var w=new DemoWorld();w.NewGame(0);w.SimulationPaused=true;w.Player.CargoMax=100000;return w;}
 static EncounterF Enter(DemoWorld w,string id){var e=w.AddSiteN(id,w.SystemId);w.Undock();w.Player.CombatHull="frigate";var site=w.UtilitySites.First(s=>s.Id=="f:"+e.Id);site.Signal=100;Check(w.EnterEncounterF(site.Id),"resolved physical entry / "+id);return e;}
 static DemoWorld Reload(DemoWorld w){w.Save();var load=new DemoWorld();Check(load.Load(),"Stage N campaign loads");return load;}
 static void Kill(DemoWorld w,SpaceTarget t){w.ActiveEncounterF!.GraphL!.Contributions[t.Id]=new(){{"player",100}};w.DamageAuditF(t);}
 static UtilityHack Hack(DemoWorld w,EncounterF e){var t=w.Targets.First(t=>t.SiteKind=="Data");w.SelectedId=w.LockedId=t.Id;w.Player.Position=t.Position;Check(w.ToggleUtility(6),"real analyzer establishes link");return w.UtilityHackState!;}
 public static void Run(){checks=0;string dir=Path.Combine(Path.GetTempPath(),"stage-n-"+Guid.NewGuid().ToString("N"));var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);SkillCatalog.VerificationAllV=false;try{
  Check(SiteCatalogN.All.Length==128&&SiteCatalogN.All.Select(p=>p.Id).Distinct().Count()==128,"128 distinct adaptation profiles");
  foreach(var p in SiteCatalogN.All){GraphCompilerL.Start(GraphCompilerL.Exploration(p.Definition),DateTime.UtcNow,DateTime.UtcNow.AddHours(3),1);var copy=SiteCatalogN.Copy(p);Check(copy.Id==p.Id&&copy.Pockets==p.Pockets&&copy.Version==1,"profile snapshot and graph compile / "+p.Id);}
  var directional=World();directional.Undock();directional.Targets=[new(){Id="scan-ship",Kind=TargetKind.Raider,Name="Patrol",Hull=100,Position=new(1000,0,0)},new(){Id="scan-rock",Kind=TargetKind.Asteroid,Name="Rock",Hull=100,Ore=10,Position=new(1500,0,0)}];var contacts=directional.DirectionalScan();Check(contacts.First(c=>c.Id=="scan-ship").IsShip&&!contacts.First(c=>c.Id=="scan-rock").IsShip,"directional results distinguish ships from asteroids for UI filter");
  var legacy=World();var old=new UtilitySite{Id="legacy-hacked",System=legacy.SystemId,Completed=true,Signal=100};Check(legacy.ProbeWarpable(old),"hacked legacy archive remains warpable for physical loot recovery");var older=legacy.AddEncounterF("archive",legacy.SystemId,true);older.State="Completed";var oldSite=legacy.UtilitySites.First(s=>s.Id=="f:"+older.Id);oldSite.Completed=true;Check(legacy.ProbeWarpable(oldSite),"completed inherited encounter retains its original return rules");var hazard=legacy.AddSiteN("n_Angel_ghost",legacy.SystemId);Check(legacy.UtilitySites.First(s=>s.Id=="f:"+hazard.Id).Kind=="Data","covert facility is classified as data signature");
  var survey=World();survey.EnsureProbeCatalog();var local=survey.Exploration.Encounters.Where(e=>e.ProfileN!=null).ToArray();Check(local.Length==8,"regional initial survey has finite family inventory");Check(local.Where(e=>e.ProfileN!.Faction!="").All(e=>e.ProfileN!.Faction==survey.RegionalFactionN()),"regional faction controls local pool");survey.EnsureProbeCatalog();Check(survey.Exploration.Encounters.Count(e=>e.ProfileN!=null)==8,"repeat refresh cannot duplicate initial survey");Check(survey.RequestRegionalSurveyN()=="Local survey refreshed.","station publishes remaining legal rating inventory");int count=survey.Exploration.Encounters.Count;survey.RequestRegionalSurveyN();Check(survey.Exploration.Encounters.Count==count,"station cannot replenish unexpired consumed sites");
  var discovery=World();var unknown=discovery.AddSiteN("n_Angel_Data_1",discovery.SystemId);discovery.Undock();var signature=discovery.UtilitySites.First(s=>s.Id=="f:"+unknown.Id);discovery.ProbeSelection=signature.Id;signature.Signal=99.99f;Check(!discovery.ProbeWarpable(signature)&&!discovery.WarpUtilitySite()&&!discovery.EnterEncounterF(signature.Id),"99.99 percent cannot warp or directly enter signature");signature.Signal=24;Check(discovery.ProbeResultGroup(signature)=="Cosmic Signature"&&discovery.ProbeResultName(signature)=="Unknown","partial result hides site identity");signature.Signal=75;Check(discovery.ProbeResultName(signature)==signature.Name&&!discovery.BookmarkProbeResult(signature.Id),"75 percent identifies but cannot bookmark");
  discovery.ScanProbes.Clear();for(int i=0;i<8;i++)discovery.ScanProbes.Add(new(){System=discovery.SystemId});discovery.MoveProbeFormation(new(signature.X,signature.Y,signature.Z));discovery.SetProbeRange(.25f);Check(discovery.AnalyzeUtilityProbes(),"real probe job starts");discovery.UpdateUtility(discovery.ProbeScanLeft+.01f);Check(signature.Signal==100&&discovery.ProbeWarpable(signature),"eight probes resolve low difficulty signature");signature.Ignored=true;var scanned=Reload(discovery);var savedSig=scanned.UtilitySites.First(s=>s.Id==signature.Id);Check(savedSig.Signal==100&&savedSig.Ignored,"observed signature and ignore state survive campaign reload");Check(scanned.EnterEncounterF(signature.Id),"resolved signature admits ship");
  foreach(var f in SiteCatalogN.Factions)foreach(int rating in Enumerable.Range(1,10)){var w=World();var e=Enter(w,$"n_{f}_ded_{rating}");Check(w.Targets.Count(t=>t.Kind==TargetKind.Raider)==e.ProfileN!.Groups,"rating roster is physical / "+f+rating);Check(e.GraphL!.Npcs.Count==e.ProfileN.Groups&&e.GraphL.Npcs.Values.Any(n=>n.Ewar.Length>0),"native EWAR roles registered / "+f+rating);if(rating>=5)Check(e.GraphL.Npcs.Values.Any(n=>n.Role=="logistics")&&w.Targets.Any(t=>t.Profile?.Support.Length>0),"high-end repair ships have fitted remote support / "+f+rating);}
  var gate=World();var ge=Enter(gate,"n_Angel_ded_2");Check(gate.AdvancePocketF(ge.Id).Contains("locked"),"blitz gate locked before commander trigger");var commander=gate.Targets.First(t=>t.Id.Contains(":commander:"));Kill(gate,commander);Check(ge.GraphL!.Drops[commander.Id].Loot.ContainsKey("n_gate_key")&&ge.GraphL.Drops[commander.Id].BountyPaid,"commander seals physical key and bounty receipt");decimal paid=gate.Balance;gate.DamageAuditF(commander);Check(gate.Balance==paid&&ge.GraphL.Drops.Count==1,"repeated destruction cannot duplicate bounty or loot");gate.Player.Position=commander.Position;gate.SelectedId="wreck_"+commander.Id;Check(gate.LootUtilityTarget()&&gate.ItemCount("n_gate_key",false)==1,"physical commander wreck transfers gate key into cargo");Check(ge.PocketReady&&gate.Targets.Any(t=>t.Kind==TargetKind.Raider&&t.Alive),"commander trigger enables non-kill-all blitz");Check(gate.AdvancePocketF(ge.Id).Contains("Approach"),"physical gate range required");gate.Player.Position=gate.Targets.First(t=>t.Id.Contains(":gate:")).Position;Check(gate.AdvancePocketF(ge.Id)==""&&ge.Pocket==1,"blitz moves to next room");var same=gate.Targets.First(t=>t.Kind==TargetKind.Raider);same.Armor=12;var loaded=Reload(gate);var le=loaded.Exploration.Encounters.First(e=>e.Id==ge.Id);Check(le.Pocket==1&&loaded.Targets.First(t=>t.Id==same.Id).Armor==12,"room and NPC damage survive reload");loaded.EnterGrid("belt",false);Check(loaded.EnterEncounterF("f:"+le.Id)&&loaded.Targets.First(t=>t.Id==same.Id).Armor==12,"reentry preserves roster damage");
  var denied=World();var de=denied.AddSiteN("n_Angel_ded_1",denied.SystemId);denied.UtilitySites.First(s=>s.Id=="f:"+de.Id).Signal=100;denied.Undock();denied.Player.CombatHull="battleship";Check(!denied.EnterEncounterF("f:"+de.Id),"rating one rejects oversized hull");
  var hack=World();hack.UtilityTrial("cruiser");Check(hack.FitUtility(UtilityCatalog.All.First(d=>d.Kind=="Data").Id,true,6),"fitted data analyzer consumed from inventory");var he=Enter(hack,"n_Guristas_Data_1");var board=Hack(hack,he);Check(board.HexN&&board.Nodes.Count(n=>n.Kind=="Core")==1,"N analyzer board has connected hex profile and one core");Check(!hack.ClickUtilityHack(48),"unreachable node rejected");for(int i=0;i<49;i++)foreach(int j in DemoWorld.HackNeighborsN(i))Check(DemoWorld.HackNeighborsN(j).Contains(i),"hex adjacency symmetric / "+i+"-"+j);
  board.Nodes[1]=new(){Kind="Firewall",Open=true,Hp=100,Strength=10};board.Tools=["Rot","Vector","Repair","Shield"];Check(hack.UseUtilityHackTool(0,1)&&board.Nodes[1].Hp==50,"kernel rot halves coherence");Check(hack.UseUtilityHackTool(0,1)&&board.VectorTurnsN==3,"secondary vector installs three-turn effect");board.Coherence=40;Check(hack.UseUtilityHackTool(0,0)&&board.RepairTurnsN==3,"self repair installs three-turn effect");Check(hack.UseUtilityHackTool(0,0)&&board.ShieldTurnsN==2,"shield installs two retaliation protections");hack.HackTurnN(board);Check(board.Nodes[1].Hp==30&&board.Coherence==Math.Min(board.MaxCoherence,50)&&board.VectorTurnsN==2,"tool effects advance on board turns");board.Nodes[2]=new(){Kind="Cache",Open=true,Tool="Rot"};board.Tools=["Repair","Shield","Vector"];board.UtilitySlots=3;Check(!hack.ClickUtilityHack(2)&&!board.Nodes[2].Cleared,"full utility slots preserve revealed cache");board.Tools.RemoveAt(0);Check(hack.ClickUtilityHack(2)&&board.Tools.Last()=="Rot","released utility slot collects sealed deferred tool");var toolsSaved=Reload(hack);var restored=toolsSaved.UtilityHackState!;Check(restored.HexN&&restored.VectorTurnsN==1&&restored.RepairTurnsN==1&&restored.ShieldTurnsN==2,"mid-hack timed utility state persists");
  var win=World();win.UtilityTrial("cruiser");win.FitUtility(UtilityCatalog.All.First(d=>d.Kind=="Data").Id,true,6);var we=Enter(win,"n_Guristas_Data_1");var wb=Hack(win,we);int core=Array.FindIndex(wb.Nodes,n=>n.Kind=="Core");for(int i=1;i<49;i++)if(i!=core)wb.Nodes[i]=new();for(int i=1;i<49;i++)if(i!=core)win.ClickUtilityHack(i);for(int i=0;i<30&&!wb.Complete;i++)win.ClickUtilityHack(core);Check(wb.Won&&win.Targets.First(t=>t.Id==wb.Target).Hacked,"real analyzer wins reachable core fixture");float before=win.ItemCount("e_decryptor",false);Check(win.LootUtilityTarget()&&win.ItemCount("e_decryptor",false)>before,"hack loot enters physical inventory");var wonSave=Reload(win);Check(wonSave.Targets.First(t=>t.Id==wb.Target).Contents.Values.All(q=>q<=0),"depleted hacked container does not reroll on load");
  var competitive=World();competitive.EnsurePopulationC();var co=competitive.AddSiteN("n_Angel_anomaly_1",competitive.SystemId);var scout=competitive.Population.Pilots.First(p=>p.Role=="Scout"&&p.System==competitive.SystemId);co.NextCompetitorN=competitive.Now;competitive.TickSitesN(1);Check(scout.Knowledge.ContainsKey("site:"+co.Id)&&co.State=="Available","competitor must observe public site before consuming it");for(int i=0;i<100&&co.State=="Available";i++){co.NextCompetitorN=competitive.Now;competitive.TickSitesN(1);}Check(co.State=="Expired"&&scout.Cargo.GetValueOrDefault("salvage")>=3,"observed competitor consumes finite site into persistent cargo");Check(!competitive.ProbeWarpable(competitive.UtilitySites.First(s=>s.Id=="f:"+co.Id)),"competing explorer consumption invalidates warp authority");
  var control=World();var ce=Enter(control,"n_cache_1");float hp=control.Player.Shield;control.TickSitesN(1);Check(control.Player.Shield<hp,"unresolved reservoir applies actual hazard damage");var bypass=control.Targets.First(t=>t.Id.Contains(":bypass:"));bypass.Hacked=true;control.EvaluateEncounterF(ce);Check(ce.PocketReady&&ce.Events.Contains("bypass:0"),"alternate hack route opens cache gate");hp=control.Player.Shield;control.TickSitesN(1);Check(control.Player.Shield==hp,"bypass stops hazard");var csave=Reload(control);Check(csave.Exploration.Encounters.First(e=>e.Id==ce.Id).Events.Contains("bypass:0"),"hazard alternative decision survives reload");
  var ghost=World();var gh=Enter(ghost,"n_Angel_ghost");Check(gh.HazardUntilN>ghost.Now&&gh.HazardUntilN<=ghost.Now.AddMinutes(3),"random ghost timer begins at entry");var original=gh.HazardUntilN;ghost.EnterGrid("belt",false);Check(ghost.EnterEncounterF("f:"+gh.Id)&&gh.HazardUntilN==original,"ghost reentry does not reset hidden deadline");gh.HazardUntilN=ghost.Now.AddSeconds(-1);ghost.TickSitesN(1);Check(gh.State=="Failed"&&ghost.Targets.Where(t=>t.Kind==TargetKind.Container).All(t=>t.Destroyed&&t.Contents.Count==0),"ghost timeout explodes physical containers");Check(!ghost.EnterEncounterF("f:"+gh.Id),"detonated site cannot reopen");
  var expedition=World();var ex=Enter(expedition,"n_Angel_unrated_1");for(int i=0;i<40&&!expedition.Exploration.Encounters.Any(e=>e.Parent==ex.Id);i++){ex.ExpeditionRolledN=false;expedition.CompleteSiteN(ex);}var child=expedition.Exploration.Encounters.First(e=>e.Parent==ex.Id);Check(child.ProfileN!.Leg==2&&child.Expires==expedition.Now.AddHours(24)&&child.System!=expedition.SystemId,"expedition creates physical next leg in linked system with saved expiry");int children=expedition.Exploration.Encounters.Count(e=>e.Parent==ex.Id);expedition.CompleteSiteN(ex);Check(expedition.Exploration.Encounters.Count(e=>e.Parent==ex.Id)==children,"sealed escalation choice cannot reroll");var esave=Reload(expedition);var savedChild=esave.Exploration.Encounters.First(e=>e.Id==child.Id);Check(savedChild.Parent==ex.Id&&savedChild.ExpeditionRootN==ex.Id&&savedChild.Expires==child.Expires,"multi-leg ancestry and expiry persist");
  var copyProfile=esave.Exploration.Encounters.First(e=>e.Id==ex.Id).ProfileN!;copyProfile.Groups=99;Check(SiteCatalogN.Get(copyProfile.Id).Groups!=99,"active profile snapshot isolated from catalogue");
  Console.WriteLine($"{checks} Stage N assertions passed.");
 }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(dir))Directory.Delete(dir,true);}}
}
